    {
      "card": "Business Silver Rewards Card",
      "best_for": "Business applicants who can wait until the next promotional window",
      "offer": "First-year annual fee waived.",
      "requirement": "Open the account between November 15, 2025 and January 15, 2026.",
      "note": "This is a fee waiver rather than a points or cash-back sign-up bonus. The standard annual fee after year one is $122.50."
    }
